"""Pixel-locked overlay: owner-approved cart/search icon correction only.

Applied to the SHA-verified unmodified STAGE02 PNG at render time.
Only two fixed rectangles are replaced; rest of the image is unchanged.
"""
import base64
import hashlib
import io
import zlib

from PIL import Image

SOURCE_SHA256 = "e4e75353fe816dc11fc75391b15de7aef60ff221b8ca10ec66d90ad08dc2e4b1"
APPROVED_CORRECTED_PIXEL_SHA256 = "e088d14ebb5e04ead99d2d84c6cf670c450ac0240bbc11992cebf19e085ce4af"
ALLOWED_RECTANGLES = ((863, 25, 48, 42), (1136, 25, 49, 42))
PATCHES = (
    ("", "923ff00b56024546403d66199afddaa4f1fe0441334dcf8db4750fe7fff4b588"),
    ("", "ab8440dd6379c9b1c797a85db2576461b406308f29f1eece1b88beeb84750f2b"),
)

def corrected_png(source_png: bytes) -> tuple[bytes, str]:
    if hashlib.sha256(source_png).hexdigest() != SOURCE_SHA256:
        raise ValueError("SOURCE_SHA_MISMATCH")
    src = Image.open(io.BytesIO(source_png))
    if src.size != (1536, 1024) or src.mode != "RGB":
        raise ValueError("SOURCE_IMAGE_FORMAT_MISMATCH")
    result = src.copy()
    for (x,y,w,h), (encoded, expected_sha) in zip(ALLOWED_RECTANGLES, PATCHES):
        patch = zlib.decompress(base64.b64decode(encoded))
        if len(patch) != w*h*3 or hashlib.sha256(patch).hexdigest() != expected_sha:
            raise ValueError("APPROVED_PATCH_SHA_MISMATCH")
        result.paste(Image.frombytes("RGB", (w,h), patch), (x,y))
    pixel_sha = hashlib.sha256(result.tobytes()).hexdigest()
    if pixel_sha != APPROVED_CORRECTED_PIXEL_SHA256:
        raise ValueError("PIXEL_QA_MISMATCH")
    out = io.BytesIO()
    result.save(out, format="PNG")
    return out.getvalue(), pixel_sha
